mapper.select:
select
wr.Wr_Title as wrTitle, mn.* from OA_Project_Report mn left join OA_Work_Report wr on wr.Wr_Id=mn.Wr_Id
where 1=1 and
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Pr_Create_Time desc

select sum(Pr_Done_Last_Year) as ipvDoneLastYearTotal, sum(Pr_Planned_Investment) as ipvPlannedInvTotal, sum(Pr_Complete_Inv) as prCompleteInvTotal, sum(Pr_Year_Inv) as prYearInvTotal, sum(Pr_Month_Inv) as prMonthInvTotal from OA_Project_Report mn left join OA_Work_Report wr on wr.Wr_Id = mn.Wr_Id where mn.Pr_Type = '02' and to_char(wr.Wr_Date, 'yyyy-MM') = concat(#{params.year}, '-', #{params.month}) and wr.Wr_State = 7 and mn.P_Id in (select pro.P_Id from Pre_Project pro left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department where pro.deleted = false and pro.State = 7
and pro.Te_Id=#{params.teId}
and pro.p_Id=#{params.pId}
and pro.P_Type=#{params.pType}
and INSTR(pro.P_Name,#{params.pName})
and INSTR(prod.D_Name,#{pCompetentDepartment})
)

select sum(Pr_Done_Last_Year) as ipvDoneLastYearTotal, sum(Pr_Planned_Investment) as ipvPlannedInvTotal, sum(Pr_Complete_Inv) as prCompleteInvTotal, sum(Pr_Year_Inv) as prYearInvTotal, sum(Pr_Month_Inv) as prMonthInvTotal from OA_Project_Report mn left join OA_Work_Report wr on wr.Wr_Id = mn.Wr_Id where mn.Pr_Type = '02' and date_format(wr.Wr_Date, '%Y-%m') = concat(#{params.year}, '-', #{params.month}) and wr.Wr_State = 7 and mn.P_Id in (select pro.P_Id from Pre_Project pro left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department where pro.deleted = false and pro.State = 7
and pro.Te_Id=#{params.teId}
and pro.P_Type=#{params.pType}
and INSTR(pro.P_Name,#{params.pName})
and INSTR(prod.D_Name,#{pCompetentDepartment})
)

select sum(Pr_Done_Last_Year) as ipvDoneLastYearTotal, sum(Pr_Planned_Investment) as ipvPlannedInvTotal, sum(Pr_Complete_Inv) as prCompleteInvTotal, sum(Pr_Year_Inv) as prYearInvTotal, sum(Pr_Month_Inv) as prMonthInvTotal from OA_Project_Report mn left join OA_Work_Report wr on wr.Wr_Id = mn.Wr_Id where mn.Pr_Type = '02' and to_char(wr.Wr_Date, 'yyyy-MM') = concat(#{params.year}, '-', #{params.month}) and wr.Wr_State = 7 and mn.P_Id in (select pro.P_Id from Pre_Project pro left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department where pro.deleted = false and pro.State = 7
and pro.Te_Id=#{params.teId}
and pro.P_Type=#{params.pType}
and INSTR(pro.P_Name,#{params.pName})
and INSTR(prod.D_Name,#{pCompetentDepartment})
)
